import numpy as np
def read(f):
    lines=open(f).read().split('\n'); n=int(lines[0]); P=[]
    for l in lines[2:2+n]:
        p=l.split(); P.append([float(v) for v in p[1:4]])
    return np.array(P)
for f in ['start.xyz','pre.xyz']:
    P=read(f)
    D=np.linalg.norm(P[:,None]-P[None,:],axis=-1)
    print(f, 'C1-C5', round(D[0,4],2), 'C2-B3', round(D[1,8],2), 'min heavy-heavy nonbond', round(min(D[i,j] for i in range(34) for j in range(i+2,34)),2))
